dashboard.definition:
{
    "title": "AI Governance",
    "description": "Home: one card per AI Governance dashboard with a live count, and the scoreboard",
    "dataSources": {
        "ds_card_01": {
            "type": "ds.search",
            "name": "AI Governance Overview",
            "options": {
                "query": "index=gen_ai_log `exclude_scoring_sourcetypes` | stats count as v",
                "queryParameters": {
                    "earliest": "-24h",
                    "latest": "now"
                }
            }
        },
        "ds_card_02": {
            "type": "ds.search",
            "name": "Tokenomics",
            "options": {
                "query": "index=gen_ai_log `exclude_scoring_sourcetypes` eventtype=gen_ai_inference | stats sum(gen_ai.usage.total_tokens) as v",
                "queryParameters": {
                    "earliest": "-24h",
                    "latest": "now"
                }
            }
        },
        "ds_card_03": {
            "type": "ds.search",
            "name": "Prompt Injection Detection",
            "options": {
                "query": "index=gen_ai_log `exclude_scoring_sourcetypes` gen_ai.policy.blocked=\"true\" | stats count as v",
                "queryParameters": {
                    "earliest": "-24h",
                    "latest": "now"
                }
            }
        },
        "ds_card_04": {
            "type": "ds.search",
            "name": "Compromised Identity",
            "options": {
                "query": "`genai_cii_failed_checks` | stats count as v",
                "queryParameters": {
                    "earliest": "-7d",
                    "latest": "now"
                }
            }
        },
        "ds_score_1": {
            "type": "ds.search",
            "name": "GenAI events",
            "options": {
                "query": "index=gen_ai_log `exclude_scoring_sourcetypes` | stats count as v",
                "queryParameters": {
                    "earliest": "-24h",
                    "latest": "now"
                }
            }
        },
        "ds_score_2": {
            "type": "ds.search",
            "name": "Users",
            "options": {
                "query": "index=gen_ai_log `exclude_scoring_sourcetypes` | stats dc(user) as v",
                "queryParameters": {
                    "earliest": "-24h",
                    "latest": "now"
                }
            }
        },
        "ds_score_3": {
            "type": "ds.search",
            "name": "Policy blocks",
            "options": {
                "query": "index=gen_ai_log `exclude_scoring_sourcetypes` gen_ai.policy.blocked=\"true\" | stats count as v",
                "queryParameters": {
                    "earliest": "-24h",
                    "latest": "now"
                }
            }
        },
        "ds_score_4": {
            "type": "ds.search",
            "name": "Safety violations",
            "options": {
                "query": "index=gen_ai_log `exclude_scoring_sourcetypes` gen_ai.safety.violated=\"true\" | stats count as v",
                "queryParameters": {
                    "earliest": "-24h",
                    "latest": "now"
                }
            }
        },
        "ds_score_5": {
            "type": "ds.search",
            "name": "PII detections",
            "options": {
                "query": "index=gen_ai_log `exclude_scoring_sourcetypes` gen_ai.pii.detected=\"true\" | stats count as v",
                "queryParameters": {
                    "earliest": "-24h",
                    "latest": "now"
                }
            }
        }
    },
    "visualizations": {
        "viz_header": {
            "type": "splunk.markdown",
            "options": {
                "fontColor": "#FFFFFF",
                "backgroundColor": "transparent",
                "markdown": "# AI Governance\n\nTA-gen_ai_cim normalizes GenAI telemetry from index gen_ai_log into the gen_ai.* schema and turns it into governance: safety, privacy, cost, prompt injection and, with Cisco Identity Intelligence, compromised identities. Each card opens a dashboard; the number on the right is that dashboard's own data."
            }
        },
        "viz_rect_01": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#31373E",
                "fillOpacity": 1,
                "rx": 8,
                "strokeColor": "#31373E",
                "strokeWidth": 1
            }
        },
        "viz_md_01": {
            "type": "splunk.markdown",
            "options": {
                "fontColor": "#FFFFFF",
                "backgroundColor": "transparent",
                "markdown": "## 01 AI Governance Overview\nSafety, privacy, policy and cost posture across every GenAI application  \n[Open AI Governance Overview](/app/TA-gen_ai_cim/ai_governance_overview)"
            }
        },
        "viz_count_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_card_01"
            },
            "options": {
                "backgroundColor": "#31373E",
                "majorColor": "#FFFFFF",
                "underLabel": "GenAI events, last 24h",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0
            }
        },
        "viz_rect_02": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#31373E",
                "fillOpacity": 1,
                "rx": 8,
                "strokeColor": "#31373E",
                "strokeWidth": 1
            }
        },
        "viz_md_02": {
            "type": "splunk.markdown",
            "options": {
                "fontColor": "#FFFFFF",
                "backgroundColor": "transparent",
                "markdown": "## 02 Tokenomics\nToken usage and calculated cost by provider, model and application  \n[Open Tokenomics](/app/TA-gen_ai_cim/tokenomics)"
            }
        },
        "viz_count_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_card_02"
            },
            "options": {
                "backgroundColor": "#31373E",
                "majorColor": "#FFFFFF",
                "underLabel": "tokens, last 24h",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0
            }
        },
        "viz_rect_03": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#31373E",
                "fillOpacity": 1,
                "rx": 8,
                "strokeColor": "#31373E",
                "strokeWidth": 1
            }
        },
        "viz_md_03": {
            "type": "splunk.markdown",
            "options": {
                "fontColor": "#FFFFFF",
                "backgroundColor": "transparent",
                "markdown": "## 03 Prompt Injection Detection\nPrompt-injection attempts from Cisco AI Defense, the ML model and the GenAI judge  \n[Open Prompt Injection Detection](/app/TA-gen_ai_cim/prompt_injection_detection)"
            }
        },
        "viz_count_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_card_03"
            },
            "options": {
                "backgroundColor": "#31373E",
                "majorColor": "#FFFFFF",
                "underLabel": "policy blocks, last 24h",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0
            }
        },
        "viz_rect_04": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#31373E",
                "fillOpacity": 1,
                "rx": 8,
                "strokeColor": "#31373E",
                "strokeWidth": 1
            }
        },
        "viz_md_04": {
            "type": "splunk.markdown",
            "options": {
                "fontColor": "#FFFFFF",
                "backgroundColor": "transparent",
                "markdown": "## 04 Compromised Identity\nCisco Identity Intelligence failed checks joined with Cisco AI Defense blocks (Lab 5)  \n[Open Compromised Identity](/app/TA-gen_ai_cim/compromised_identity)"
            }
        },
        "viz_count_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_card_04"
            },
            "options": {
                "backgroundColor": "#31373E",
                "majorColor": "#FFFFFF",
                "underLabel": "CII failed checks, last 7d",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0
            }
        },
        "viz_score_title": {
            "type": "splunk.markdown",
            "options": {
                "fontColor": "#FFFFFF",
                "backgroundColor": "transparent",
                "markdown": "## Scoreboard, last 24h\nHeadline numbers from gen_ai_log (scoring and response-action write-backs excluded)."
            }
        },
        "viz_score_1": {
            "type": "splunk.singlevalue",
            "title": "GenAI events",
            "dataSources": {
                "primary": "ds_score_1"
            },
            "options": {
                "backgroundColor": "#31373E",
                "majorColor": "#FFFFFF",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0
            }
        },
        "viz_score_2": {
            "type": "splunk.singlevalue",
            "title": "Users",
            "dataSources": {
                "primary": "ds_score_2"
            },
            "options": {
                "backgroundColor": "#31373E",
                "majorColor": "#FFFFFF",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0
            }
        },
        "viz_score_3": {
            "type": "splunk.singlevalue",
            "title": "Policy blocks",
            "dataSources": {
                "primary": "ds_score_3"
            },
            "options": {
                "backgroundColor": "#31373E",
                "majorColor": "#FFFFFF",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0
            }
        },
        "viz_score_4": {
            "type": "splunk.singlevalue",
            "title": "Safety violations",
            "dataSources": {
                "primary": "ds_score_4"
            },
            "options": {
                "backgroundColor": "#31373E",
                "majorColor": "#FFFFFF",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0
            }
        },
        "viz_score_5": {
            "type": "splunk.singlevalue",
            "title": "PII detections",
            "dataSources": {
                "primary": "ds_score_5"
            },
            "options": {
                "backgroundColor": "#31373E",
                "majorColor": "#FFFFFF",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0
            }
        }
    },
    "inputs": {},
